import maplibregl from 'maplibre-gl';
import { PMTiles, register } from 'pmtiles';

// 1️⃣ Register the archive (remote or local)
const pm = new PMTiles('https://my.cdn.com/tiles/world.pmtiles');
register(pm);

// 2️⃣ Initialise the map
const map = new maplibregl.Map({
  container: 'map',
  style: {
    version: 8,
    sources: {},
    layers: []
  },
  center: [0, 0],
  zoom: 2
});

// 3️⃣ Add source + layer once the style is ready
map.on('load', () => {
  map.addSource('world-pmtiles', {
    type: 'vector',
    url: 'pmtiles://world.pmtiles'
  });

  map.addLayer({
    id: 'countries',
    type: 'fill',
    source: 'world-pmtiles',
    'source-layer': 'admin',
    paint: {
      'fill-color': '#4a90e2',
      'fill-opacity': 0.4
    }
  });
});
```

That’s it—your `.pmtiles` archive is now a first‑class source in MapLibre GL JS! 🎉

